import{_ as e,o as a,c as n,a as r}from"./app.1844d130.js";var i="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/01-eschbacher-klippen-panorama.jpg",s="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/02-infotafel-usinger-quarzgang.jpg",t="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/03-waldgeist-troll.jpg",l="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/04-waldgeist-zauberer.jpg",h="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/14-ueberblick-camp-und-klippen.jpg",u="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/05-antennenaufbau-teleskop-vertikal.jpg",d="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/06-vertikal-mit-radials.jpg",c="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/07-efhw-im-wald.jpg",p="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/08-vertikaldipol-vor-den-klippen.jpg",o="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/09-magloop-am-fels.jpg",m="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/13-shack-auf-dem-baumstumpf.jpg",g="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/10-wanderer-schauen-vorbei.jpg",b="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/12-kloenschnak-am-camp.jpg",f="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/11-heisse-wuerstchen.jpg",k="/aktivitaeten/Eyeball-QSO-Eschbacher-Klippen-2026-10-31/15-gruppenbild.jpg";const w={},v=r('<h1 id="su\xDFes-saures-oder-qso-halloween-an-den-eschbacher-klippen" tabindex="-1"><a class="header-anchor" href="#su\xDFes-saures-oder-qso-halloween-an-den-eschbacher-klippen" aria-hidden="true">#</a> S\xFC\xDFes, Saures oder QSO? Halloween an den Eschbacher Klippen</h1><h2 id="ruckblick-2-draussenfunker-hessen-eyeball-qso-\u2013-31-oktober-2026-\u2013-eschbacher-klippen-hochtaunus" tabindex="-1"><a class="header-anchor" href="#ruckblick-2-draussenfunker-hessen-eyeball-qso-\u2013-31-oktober-2026-\u2013-eschbacher-klippen-hochtaunus" aria-hidden="true">#</a> R\xFCckblick: 2. Draussenfunker Hessen Eyeball QSO \u2013 31. Oktober 2026 \u2013 Eschbacher Klippen (Hochtaunus)</h2><p>Nach Villmar war klar: Das war kein Zufall, das war der Anfang. Martin (DH3FR) startete die Initiative und brachte die Eschbacher Klippen als Location ins Spiel, Max (DM6AX, ehemals DA6MAX) war sofort dabei, und schon stand das zweite Hessen-Eyeball-QSO im Kalender. Termin: Halloween. Ort: die Eschbacher Klippen. Mehr Kulisse geht kaum: ein Felsmassiv, Herbstlaub in allen Farben und dazu ein Haufen Funkamateure mit Antennen im Gep\xE4ck. Gespenster sind uns keine begegnet. Vermutlich waren die auf 40 m besch\xE4ftigt.</p><p>Das Wetter? Grau in grau, aber trocken. Der Plan B mit dem Sonntag durfte in der Schublade bleiben. Von etwa 11 bis 17 Uhr war an den Klippen Funkbetrieb.</p><p><img src="'+i+'" alt="Die Eschbacher Klippen unter grauem Herbsthimmel"></p><h2 id="wo-der-quarz-zu-hause-ist" tabindex="-1"><a class="header-anchor" href="#wo-der-quarz-zu-hause-ist" aria-hidden="true">#</a> Wo der Quarz zu Hause ist</h2><p>Die Eschbacher Klippen (Buch- und Saienstein) haben mehr auf dem Kasten als so mancher von uns auf dem Frequenzzettel. Laut Infotafel sind sie Teil des Usinger Quarzganges, der sich im Gel\xE4nde \xFCber rund 6 km verfolgen l\xE4sst. Der Gang ist etwa 270 Millionen Jahre alt, also j\xFCnger als der Taunus selbst (ca. 320 Mio. Jahre), und bis zu 80 m m\xE4chtig. Die Felsen sind also nur die hartn\xE4ckigsten \xDCberbleibsel eines viel gr\xF6\xDFeren Gebildes: Entlang einer St\xF6rung stie\xDFen hei\xDFe, w\xE4ssrige L\xF6sungen auf, erst schied sich Schwerspat aus, den sp\xE4ter Quarz ersetzte.</p><p>Quarz! Das Mineral, ohne das in unseren Funkger\xE4ten kaum etwas schwingt. Wir haben also quasi am Ursprung des Quarzoszillators gefunkt. Wenn das kein gutes Omen ist.</p><p><img src="'+s+'" alt="Infotafel zu den Eschbacher Klippen und dem Usinger Quarzgang"></p><h2 id="das-empfangskomitee" tabindex="-1"><a class="header-anchor" href="#das-empfangskomitee" aria-hidden="true">#</a> Das Empfangskomitee</h2><p>Am Wegesrand hielten zwei geschnitzte Waldgeister die Stellung, genau das richtige Empfangskomitee f\xFCr Halloween. Der Troll sah aus, als h\xE4tte er gerade ein Pile-Up verpasst. Der Zauberer sah aus, als h\xE4tte er es verursacht.</p><p><img src="'+t+'" alt="Geschnitzter Troll im Herbstwald"><img src="'+l+'" alt="Geschnitzter Zauberer mit spitzem Hut"></p><h2 id="die-crew-von-der-grundschule-bis-zum-urgestein" tabindex="-1"><a class="header-anchor" href="#die-crew-von-der-grundschule-bis-zum-urgestein" aria-hidden="true">#</a> Die Crew: von der Grundschule bis zum Urgestein</h2><p>Die offizielle Teilnehmerzahl? Haben wir nicht gez\xE4hlt. Funkamateure z\xE4hlt man nicht, man h\xF6rt sie. Unsere Sch\xE4tzung: bestimmt 15 OPs, wahrscheinlich mehr.</p><p>Besonders sch\xF6n war die Bandbreite: Funk-Nachwuchs im Grundschulalter, frisch Gepr\xFCfte aus dem Oktober, neue OPs aus 2026 und alteingesessene Hasen mit mehreren Jahrzehnten Erfahrung. Vom ersten Rufzeichen bis zur grauen Eminenz war alles dabei, und alle haben voneinander profitiert.</p><p>Und es waren nicht nur Draussenfunker aus dem Discord da: Auch viele OPs aus den umliegenden Ortsverb\xE4nden sind vorbeigekommen und haben sich interessiert umgesehen. Willkommen im Klub!</p><p><img src="'+h+'" alt="Camp und Klippen im \xDCberblick"></p><h2 id="der-antennenzoo" tabindex="-1"><a class="header-anchor" href="#der-antennenzoo" aria-hidden="true">#</a> Der Antennenzoo</h2><p>Wenn es eine Antenne gab, die nicht aufgebaut wurde, dann lag sie vermutlich noch im Auto. Es entstand ein bunter Strau\xDF:</p><ul><li><strong>Vertikalantennen</strong>, klassisch mit Ground-Radials auf dem Boden oder elevated, die Radials auf Wanderst\xF6cken (die endlich mal eine Aufgabe jenseits des Wanderns haben)</li><li><strong>Vertikale Dipole</strong></li><li><strong>EFHW-Drahtantennen</strong></li><li><strong>Mobile KW-Antennen</strong> mit integrierter Spule</li><li><strong>Magloops</strong></li></ul><p>Als Shack dienten Campingtisch, Wiese und Baumstumpf, Hauptsache mit Aussicht.</p><p><img src="'+u+'" alt="Ein Teleskop-Vertikal wird aufgebaut"><img src="'+d+'" alt="Vertikalantenne mit Radials auf der Wiese"><img src="'+c+'" alt="Drahtantenne zwischen den Kiefern"><img src="'+p+'" alt="Antenne auf Stativ, im Hintergrund die Klippen"><img src="'+o+'" alt="Magloop vor dem Felsen"><img src="'+m+'" alt="Funkbetrieb auf dem Baumstumpf"></p><h2 id="hallo-was-macht-ihr-da" tabindex="-1"><a class="header-anchor" href="#hallo-was-macht-ihr-da" aria-hidden="true">#</a> Hallo, was macht ihr da?</h2><p>Die Wanderer und Naturfreunde, die vorbeikamen, waren allesamt offen und interessiert. Und das fiel auf: Diesmal gab es keinerlei Ber\xFChrungs\xE4ngste und keine Reserviertheit gegen\xFCber dem Hobby, nur echte Neugier. Fragen, Staunen, Nachfragen. Vielleicht liegt es an Halloween: Wer Leute mit Drahtgeflecht im Wald sieht, will wissen, was da gespielt wird. Ob jemand dachte, wir beschw\xF6ren etwas, ist nicht \xFCberliefert.</p><p><img src="'+g+'" alt="Wanderer schauen bei einer Station vorbei"></p><h2 id="der-draussenfunkerstau-auf-40-m" tabindex="-1"><a class="header-anchor" href="#der-draussenfunkerstau-auf-40-m" aria-hidden="true">#</a> Der Draussenfunkerstau auf 40 m</h2><p>Die B\xE4nder waren gut offen, und alle Stationen konnten QSO-Erfolge feiern. Der H\xF6hepunkt: das Pile-Up auf 40 m. Pl\xF6tzlich waren alle da. Als Max (DM6AX) dann nur ganz kurz QRX verk\xFCndete, passierte etwas Sch\xF6nes: Die wartenden Draussenfunker nutzten die Pause f\xFCr einen Kl\xF6nschnak untereinander und hielten so die Frequenz frei, bis die Aktivierung weiterging. Episch.</p><p>Ab sofort gilt daher offiziell: Ein Draussenfunker-Pile-Up hei\xDFt <strong>Draussenfunkerstau</strong>. Pile-Up klingt nach Hektik und Dr\xE4ngeln. Ein Stau dagegen ist der einzige, in dem man sich freut, drinzustehen.</p><p><img src="'+b+'" alt="Kl\xF6nschnak am Camp"></p><h2 id="su\xDFes-saures-oder-qso" tabindex="-1"><a class="header-anchor" href="#su\xDFes-saures-oder-qso" aria-hidden="true">#</a> S\xFC\xDFes, Saures oder QSO?</h2><p>S\xFC\xDFes gab es reichlich: Muffins und Halloween-Gummib\xE4rchen. Dazu gab es hei\xDFe W\xFCrstchen, um die sich Martin (DH3FR) gek\xFCmmert hat, serviert im Topf mit Windschutz auf dem Campingtisch, wie es sich f\xFCr Draussenfunker geh\xF6rt. Saures gab es nur, wenn jemand auf einer besetzten Frequenz gerufen hat.</p><p><img src="'+f+'" alt="Hei\xDFe W\xFCrstchen im Topf mit Windschutz"></p><h2 id="fazit-ein-herbstnachmittag-der-in-erinnerung-bleibt" tabindex="-1"><a class="header-anchor" href="#fazit-ein-herbstnachmittag-der-in-erinnerung-bleibt" aria-hidden="true">#</a> Fazit: Ein Herbstnachmittag, der in Erinnerung bleibt</h2><p>Ein ganz toller Halloween-Nachmittag liegt hinter uns. Ein riesiges <strong>Danke</strong> an alle, die dabei waren, ob Draussenfunker aus dem Discord, Neuling, Veteran oder Wanderer, der stehen geblieben ist. Und ein ganz besonderes Dankesch\xF6n an Martin (DH3FR): Er hat die Initiative gestartet, die Eschbacher Klippen als Location vorgeschlagen und sich heute auch noch um die hei\xDFen W\xFCrstchen gek\xFCmmert. Martin, du bist der Held des Tages!</p><p><img src="'+k+'" alt="Gruppenbild der Draussenfunker Hessen an den Eschbacher Klippen"></p><p>Nach dem ersten Hessen-Treffen in Villmar war das nicht das letzte: Im Fr\xFChjahr finden wir bestimmt schon die n\xE4chste Location, um hier anzukn\xFCpfen. Ortstipps nehmen wir gern im Discord entgegen.</p><p>S\xFC\xDFes, Saures oder QSO? Wir nehmen alles, und zwar bald wieder.</p><p><em>73, Max (DM6AX) &amp; Martin (DH3FR)</em><em>im Namen aller Draussenfunker Hessen</em></p>',38),z=[v];function E(D,S){return a(),n("div",null,z)}var K=e(w,[["render",E],["__file","2026-10-31-Draussenfunker-Hessen-Eyeball-QSO-Eschbacher-Klippen.html.vue"]]);export{K as default};
